import { Component, Element, Event, EventEmitter, h, Host, Listen, Method, Prop, State, Watch } from '@stencil/core';
import { FormDataEvent, FormSize, IconPosition, InputType, inputTypes, Severity, TextTransform } from '../../types';
import { AriaAttributes, extractAriaAttributes } from '../../utils/a11y-helper';

/**
 * @nativeEvent click - dispatched when input was clicked => 'event.target.value' delivers the current value
 * @nativeEvent change - dispatched when input has changed => 'event.target.value' delivers the current value
 * @nativeEvent invalid - dispatched when input is invalid => 'event.target.value' delivers the invalid value
 *
 * @slot description - named slot 'description', here is any HTML content allowed.
 * @slot label - named slot 'label', here is any HTML content allowed.
 */
@Component({
  tag: 'groupui-input',
  styleUrl: 'input.scss',
  shadow: { delegatesFocus: true },
})
export class Input {
  /**
   * severity of the input
   */
  @Prop({ reflect: true, mutable: true }) severity: Severity;

  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly inverted: boolean;

  /**
   * icon name e.g. 'clock-24'. Use the matching 24px sized icons for size m (default) and 16px sized icons for size s
   */
  @Prop({ reflect: true }) readonly icon: string;

  /**
   * sets a custom icon source e.g. '...path/clock-24.svg', overrides icon property if both are set
   */
  @Prop({ reflect: true }) readonly iconSource: string;

  /**
   * sets the size of the input field
   */
  @Prop({ reflect: true }) readonly size: FormSize = 'm';

  /**
   * position of the icon
   */
  @Prop({ reflect: true }) readonly iconPosition: IconPosition = 'left';

  /**
   * color of the icon
   */
  @Prop({ reflect: true }) readonly iconColor: string;

  /**
   * toggles readonly mode
   */
  @Prop({ reflect: true }) readonly readonly: boolean;

  /**
   * placeholder of the input-field<br>
   * ❗❗ applicable only to: VWAG
   */
  @Prop({ reflect: true }) readonly placeholder: string;

  /**
   * value of the input-field
   */
  @Prop({ reflect: true, mutable: true }) value: string;

  /**
   * sets input-field to readonly
   */
  @Prop({ reflect: true }) readonly disabled: boolean;

  /**
   * sets the maximum amount of characters of the input-field.
   * This does not work properly in Firefox for `type=number` in combination with non-digit characters.
   */
  @Prop({ reflect: true }) readonly maxlength: number;

  /**
   * determines whether maxlength should prevent input of any more characters (html default behavior).
   * For `type=number` and `maxlength` the prevention is always given.
   */
  @Prop({ reflect: true }) readonly htmlMaxlengthBehavior: boolean = false;

  /**
   * determines whether max and min should prevent input of values out of range (html default behavior).
   */
  @Prop({ reflect: true }) readonly htmlMinMaxBehavior: boolean = false;

  /**
   * sets the minimum amount of characters of the input-field
   */
  @Prop({ reflect: true }) readonly minlength: number;

  /**
   * a pattern which will be covered by validity
   */
  @Prop({ reflect: true }) readonly pattern: string;

  /**
   * displays the transformed text inside the input field
   */
  @Prop({ reflect: true }) readonly textTransform: TextTransform;

  /**
   * returns the element's current validityState state (readonly value)
   */
  @Prop({ reflect: false, mutable: true }) validity: ValidityState;

  /**
   * specifies input type, unsupported types will fall back to type=text
   */
  @Prop({ reflect: true }) readonly type: InputType = 'text';

  /**
   * name of the input element to support forms
   */
  @Prop({ reflect: true }) readonly name: string;

  /**
   * minimum value to accept for this input. To be used with type=number
   */
  @Prop({ reflect: true }) readonly min: number | string;

  /**
   * maximum value to accept for this input. To be used with type=number
   */
  @Prop({ reflect: true }) readonly max: number | string;

  /**
   * Specifies the interval between legal numbers (i.e '0.1'). To be used with type=number
   */
  @Prop({ reflect: true }) readonly step: number;

  /**
   * specifies that an input must be filled out before submitting the form
   */
  @Prop({ reflect: true }) readonly required: boolean = false;

  /**
   * sets focus automatically
   */
  // eslint-disable-next-line
  @Prop({ reflect: true }) readonly autofocus: boolean;

  /**
   * show status icon on severity danger, warning, success
   */
  @Prop({ reflect: true }) readonly showStatusIcon: boolean = false;

  /**
   * a string with placeholder about count of available and used characters. Works only
   *  in combination with maxlength.
   * Possible values:
   *  {characters-used}
   *  {characters-left}
   *  {characters-max}
   * e.g.:
   *    '{characters-used} characters used'
   *    '{characters-left} characters left'
   *    '{characters-used}/{characters-max}'
   */
  @Prop({ reflect: true }) readonly typingInfoTemplate: string;

  /**
   * When set to true, the typing information is always displayed. When set to false, it's only shown when the input has focus.
   */
  @Prop({ reflect: true }) readonly alwaysShowTypingInfo: boolean = false;

  /**
   * Aligns the typing info to the bottom left or bottom right side of the input. Won't have any effect, if a description is provided.
   */
  @Prop({ reflect: true }) readonly alignTypingInfo: 'left' | 'right' = 'left';

  /**
   * shows the description only when the component has focus
   */
  @Prop({ reflect: true }) readonly descriptionOnlyOnFocus: boolean = false;

  /**
   * disable internal validation
   */
  @Prop({ reflect: true }) readonly noValidation: boolean = false;

  /**
   * show clear icon to clear the input field
   */
  @Prop({ reflect: true }) readonly showClearIcon: boolean = false;

  /**
   * ARIA label for the clear icon.
   */
  @Prop({ reflect: true, attribute: 'a11y-label-clear-button' }) readonly a11yLabelClearButton: string = 'Clear';

  /**
   * ARIA label for the type icon. Default is the given type.
   */
  @Prop({ reflect: true, attribute: 'a11y-label-type-button' }) readonly a11yLabelTypeButton: string;

  /**
   * prefix of the input field
   */
  @Prop({ reflect: true }) readonly prefixText: string;

  /**
   * suffix of the input field
   */
  @Prop({ reflect: true }) readonly suffixText: string;

  /**
   * hide show password icon. To be used with type=password
   */
  @Prop({ reflect: true }) readonly hideShowPassword: boolean = false;

  /**
   * hide icon for type=time and type=month and spin buttons for type=number
   */
  @Prop({ reflect: true }) readonly hideTypeIndicator: boolean = false;

  @State() hasFocus: boolean;

  @State() validityState: ValidityState;

  @State() showPassword: boolean;

  /**
   * for react user only - use this instead of the native change event
   */
  @Event({ bubbles: false }) groupuiChange: EventEmitter<void>;

  /**
   * is dispatched when the value is invalid
   */
  @Event({ bubbles: false }) groupuiInvalid: EventEmitter<ValidityState>;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  /**
   * is dispatched if the clear icon is clicked
   */
  @Event({ bubbles: false }) groupuiClearClicked: EventEmitter<void>;

  @Element() host: HTMLElement;

  private ariaAttributes: AriaAttributes;

  private showPicker: boolean = false;

  @Listen('blur')
  onBlur() {
    this.hasFocus = false;
  }

  @Listen('focus')
  onFocus() {
    this.hasFocus = true;
    this.delegateFocusToNativeInput();
  }

  @Listen('click')
  onClick(event) {
    if (this.disabled) {
      event.stopImmediatePropagation();
    } else {
      this.delegateFocusToNativeInput();
    }
  }

  /**
   * function to trigger component validation manually
   */
  @Method()
  async validate() {
    this.updateValidityState({ force: true });
  }

  componentWillLoad() {
    this.ariaAttributes = extractAriaAttributes(this.host);
    this.validity = this.getValidity();
  }

  componentDidLoad() {
    this.autofocus && this.host.focus && this.host.focus();
    this.groupuiDidLoad.emit();

    this.initFormEvent();
  }

  private initFormEvent() {
    const form = this.host.closest('form');
    if (form == null) return;

    form.addEventListener('formdata', (event: FormDataEvent) => {
      event.formData.append(this.name, this.value);
    });

    form.addEventListener('submit', (event) => {
      this.updateValidityState();
      if (!this.validityState || !this.validityState.valid) {
        event.preventDefault();
      }
    });
  }

  private delegateFocusToNativeInput() {
    this.host.shadowRoot.querySelector('input').focus();
  }

  private validateRequired(): boolean {
    if (this.required) {
      return this.value !== undefined && this.value.length > 0;
    }
    return true;
  }

  private validatePattern(): boolean {
    if (this.pattern !== undefined) {
      const regex = new RegExp(this.pattern);
      return regex.test(this.value);
    }
    return true;
  }

  private validateMinLength(): boolean {
    if (this.minlength !== undefined) {
      return this.value?.length >= this.minlength || this.minlength === 0;
    }
    return true;
  }

  private validateMaxLength(): boolean {
    if (this.maxlength !== undefined && this.value !== undefined) {
      return this.value?.length <= this.maxlength;
    }
    return true;
  }

  private validateMin(): boolean {
    if (this.isValidMinMaxInputValue(this.min) && this.type === 'number') {
      const minInt = typeof this.min === 'string' ? parseInt(this.min) : this.min;

      return parseInt(this.value) >= minInt;
    }
    return true;
  }

  private validateMax(): boolean {
    if (this.isValidMinMaxInputValue(this.max) && this.type === 'number') {
      const maxInt = typeof this.max === 'string' ? parseInt(this.max) : this.max;

      return parseInt(this.value) <= maxInt;
    }
    return true;
  }

  private isValidMinMaxInputValue(value) {
    return value !== undefined && value !== '';
  }

  private handleInput = (event: InputEvent) => {
    const input: HTMLInputElement = event.target as HTMLInputElement;
    if (this.cutTooLargeNumber(input)) {
      input.value = input.value.substring(0, this.maxlength);
    }
    this.value = input.value;
  };

  private cutTooLargeNumber(input: HTMLInputElement): boolean {
    return this.type === 'number' && this.maxlength && input.value && input.value.length > this.maxlength;
  }

  private handleChange = () => {
    this.host.dispatchEvent(new window.Event('change'));
    this.groupuiChange.emit();
  };

  private handleBlur = () => {
    this.updateValidityState();
  };

  @Watch('validityState')
  onValidityStateChanged() {
    this.severity = this.validityState && this.validityState.valid ? 'none' : 'danger';
    if (!this.validityState || !this.validityState.valid) {
      this.dispatchInvalidEvent();
    }
  }

  @Watch('value')
  onValueChanged() {
    // Ensures the native input element stays in sync with external value changes.
    // Without this, the input's value and component's value prop can diverge
    // when both external updates and input events occur simultaneously.
    const inputElement = this.host.shadowRoot.querySelector('input') as HTMLInputElement;
    if (inputElement && inputElement.value !== this.value) {
      inputElement.value = this.value ?? '';
    }
  }

  private dispatchInvalidEvent() {
    this.host.dispatchEvent(new window.Event('invalid'));
    this.groupuiInvalid.emit(this.validityState);
  }

  private updateValidityState({ force = false }: { force?: boolean } = {}) {
    const validity = this.getValidity();
    this.validity = validity;

    if (!force && this.noValidation) return;
    this.validityState = validity;
  }

  private getValidity() {
    return {
      badInput: false,
      customError: false,
      patternMismatch: !this.validatePattern(),
      rangeOverflow: !this.validateMax(),
      rangeUnderflow: !this.validateMin(),
      stepMismatch: false,
      tooLong: !this.validateMaxLength(),
      tooShort: !this.validateMinLength(),
      typeMismatch: false,
      valid: this.isValid(),
      valueMissing: !this.validateRequired(),
    };
  }

  private isValid() {
    return (
      this.validateRequired() &&
      this.validatePattern() &&
      this.validateMinLength() &&
      this.validateMaxLength() &&
      this.validateMin() &&
      this.validateMax()
    );
  }

  private showTypingInfo() {
    return (this.hasFocus || this.alwaysShowTypingInfo) && this.typingInfoTemplate;
  }

  private showDescription() {
    if (!this.descriptionOnlyOnFocus) {
      return true;
    } else {
      return this.hasFocus;
    }
  }

  private applyTypingInfo() {
    if (!this.maxlength) {
      return this.typingInfoTemplate;
    }

    const length = this.value ? this.value.length : 0;
    return this.typingInfoTemplate
      .replace('{characters-left}', String(this.maxlength - length))
      .replace('{characters-used}', String(length))
      .replace('{characters-max}', String(this.maxlength));
  }

  private isReadonly(): boolean {
    return this.disabled || this.readonly;
  }

  private isLabelSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="label"]');
  }

  private isDescriptionSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="description"]');
  }

  private iconSize() {
    return this.size === 's' ? '16' : '24';
  }

  private useStatusIcon() {
    return this.showStatusIcon && this.severity && this.severity !== 'none';
  }

  private getStatusIcon() {
    switch (this.severity) {
      case 'warning':
        return `warning-filled-${this.iconSize()}`;
      case 'danger':
        return `error-filled-${this.iconSize()}`;
      case 'success':
        return `success-filled-${this.iconSize()}`;
    }
  }

  private isShowClearIcon() {
    return this.value && !this.disabled && this.showClearIcon;
  }

  private clearInput = (event) => {
    this.value = '';
    this.host.shadowRoot.querySelector('input').focus();
    this.groupuiClearClicked.emit();
    event.preventDefault();
  };

  private getInputType() {
    if (inputTypes.includes(this.type)) {
      if (this.type === 'password' && this.showPassword) {
        return 'text';
      }
      return this.type;
    }
    return 'text';
  }

  private togglePassword = () => {
    this.showPassword = !this.showPassword;
  };

  private togglePicker = () => {
    const input = this.host.shadowRoot.querySelector('input') as HTMLInputElement;
    if (!this.showPicker) {
      input.showPicker && input.showPicker();
    }
    this.showPicker = !this.showPicker;
  };

  render() {
    return (
      <Host tabIndex={this.disabled ? -1 : 0}>
        <div>
          {this.isLabelSlotProvided() && (
            <label id="label" class={{ inline: !this.value && !this.hasFocus }}>
              <slot name="label" />
            </label>
          )}
          <div id="input-wrapper" class={{ focused: this.hasFocus && !this.disabled }}>
            {(this.icon || this.iconSource) && (
              <groupui-icon
                name={this.icon}
                style={{ color: this.iconColor && this.iconColor }}
                src={this.iconSource}
                class="icon"
              />
            )}
            {this.prefixText && <groupui-text class="affix">{this.prefixText}</groupui-text>}
            <input
              type={this.getInputType()}
              disabled={this.disabled}
              tabIndex={this.disabled ? -1 : 0}
              placeholder={this.placeholder}
              onBlur={this.handleBlur}
              onInput={this.handleInput}
              onChange={this.handleChange}
              step={this.type === 'number' ? this.step : undefined}
              readOnly={this.isReadonly()}
              style={{ 'text-transform': this.textTransform }}
              autoFocus={this.autofocus}
              maxlength={this.htmlMaxlengthBehavior ? this.maxlength : undefined}
              min={this.htmlMinMaxBehavior ? this.min : undefined}
              max={this.htmlMinMaxBehavior ? this.max : undefined}
              value={this.value}
              part="input"
              aria-labelledby={this.isLabelSlotProvided() ? 'label' : undefined}
              aria-describedby={this.isDescriptionSlotProvided() ? 'description' : undefined}
              {...this.ariaAttributes}
            />
            {this.suffixText && <groupui-text class="affix">{this.suffixText}</groupui-text>}
            {this.useStatusIcon() && <groupui-icon name={this.getStatusIcon()} class="status-icon" />}
            <groupui-embedded-button
              id="clear"
              class={{ 'clear-icon': true, hidden: !this.isShowClearIcon() }}
              icon={`close-${this.iconSize()}`}
              aria-label={this.a11yLabelClearButton}
              size={this.size === 's' ? 'xxs' : 'xs'}
              disabled={this.disabled}
              onClick={this.clearInput}
            />
            {this.type === 'password' && !this.hideShowPassword && !this.disabled && this.value && (
              <groupui-embedded-button
                class="password-icon"
                icon={this.showPassword ? `hide-${this.iconSize()}` : `eye-open-${this.iconSize()}`}
                aria-label={this.a11yLabelTypeButton || 'Password'}
                size={this.size === 's' ? 'xxs' : 'xs'}
                onClick={this.togglePassword}
              />
            )}
            {this.type === 'month' && !this.hideTypeIndicator && (
              <groupui-embedded-button
                class="month-icon"
                onClick={this.togglePicker}
                icon={`calendar-${this.iconSize()}`}
                aria-label={this.a11yLabelTypeButton || 'Month'}
                size={this.size === 's' ? 'xxs' : 'xs'}
                disabled={this.disabled}
              />
            )}
            {this.type === 'time' && !this.hideTypeIndicator && (
              <groupui-embedded-button
                class="time-icon"
                onClick={this.togglePicker}
                icon={`clock-${this.iconSize()}`}
                aria-label={this.a11yLabelTypeButton || 'Time'}
                size={this.size === 's' ? 'xxs' : 'xs'}
                disabled={this.disabled}
              />
            )}
          </div>
          {this.isInfoContainerNeeded() && (
            <div id="info">
              {this.isDescriptionSlotProvided() && this.showDescription() && (
                <div id="description">
                  <slot name="description" />
                </div>
              )}
              {this.showTypingInfo() && <div id="typing-info">{this.applyTypingInfo()}</div>}
            </div>
          )}
        </div>
      </Host>
    );
  }

  private isInfoContainerNeeded() {
    return (this.isDescriptionSlotProvided() && this.showDescription()) || this.showTypingInfo();
  }
}
